"""
Flask Todo API

A single-file Flask app with clean structure: routes, error handling.
Data access is handled by the repository layer; routes never touch SQL directly.
Uses SQLite for storage and initializes the schema on startup.
"""

from flask import Flask, request, jsonify, g
from datetime import datetime, timedelta, timezone
from functools import wraps
import os
import jwt

from celery_app import send_notification_email
from repositories import (
    TaskRepository,
    UserRepository,
    init_db,
    check_password,
)

app = Flask(__name__)

app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY", "dev-secret-key")

task_repository = TaskRepository()
user_repository = UserRepository()


# ── Auth helpers ─────────────────────────────────────────────


def create_token(user_id: int, username: str) -> str:
    payload = {
        "user_id": user_id,
        "username": username,
        "exp": datetime.now(timezone.utc) + timedelta(hours=12),
    }
    return jwt.encode(payload, app.config["SECRET_KEY"], algorithm="HS256")


def decode_token(token: str) -> int | None:
    try:
        payload = jwt.decode(token, app.config["SECRET_KEY"], algorithms=["HS256"])
        return payload.get("user_id")
    except jwt.PyJWTError:
        return None


def auth_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return jsonify({"error": "authentication required"}), 401
        user_id = decode_token(auth[7:].strip())
        if user_id is None:
            return jsonify({"error": "invalid or expired token"}), 401
        g.user_id = user_id
        return fn(*args, **kwargs)

    return wrapper


# ── Routes ─────────────────────────────────────────────────────


@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    if not username or not password:
        return jsonify({"error": "username and password are required"}), 400
    if user_repository.get_by_username(username) is not None:
        return jsonify({"error": "username already taken"}), 409
    user = user_repository.create_user(username, password)
    return jsonify(user), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    if not username or not password:
        return jsonify({"error": "username and password are required"}), 400
    user = user_repository.get_by_username(username)
    if user is None or not check_password(password, user["password_hash"]):
        return jsonify({"error": "invalid credentials"}), 401
    token = create_token(user["id"], user["username"])
    return jsonify({"token": token, "user": {"id": user["id"], "username": user["username"]}})


@app.route("/tasks", methods=["GET"])
@auth_required
def list_tasks():
    return jsonify(task_repository.get_tasks(g.user_id))


@app.route("/tasks", methods=["POST"])
@auth_required
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title", "").strip()
    if not title:
        return jsonify({"error": "title is required"}), 400
    task = task_repository.create_task(g.user_id, title)
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@auth_required
def show_task(task_id: int):
    task = task_repository.get_task(task_id, g.user_id)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@auth_required
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    task = task_repository.update_task(
        task_id,
        g.user_id,
        title=data.get("title"),
        status=data.get("status"),
    )
    if task is None:
        return jsonify({"error": "task not found"}), 404
    if task["status"] == "completed":
        user = user_repository.get_by_id(task["owner_id"]) or {}
        try:
            send_notification_email.delay(
                user.get("username", ""), task["title"]
            )
        except Exception:
            # Never let a notification failure block or break the API response.
            app.logger.exception("failed to enqueue notification email")
    return jsonify(task)


init_db()

if __name__ == "__main__":
    app.run(debug=True)

"""
Repository layer for the Todo API.

Encapsulates all SQLite access. Route handlers interact with repository
objects instead of issuing raw SQL.
"""

import os
import sqlite3
from abc import ABC, abstractmethod
from datetime import datetime

import bcrypt

DEFAULT_DATABASE = os.environ.get("DATABASE", "todos.db")


def database_path() -> str:
    return os.environ.get("DATABASE", DEFAULT_DATABASE)


def get_db():
    conn = sqlite3.connect(database_path())
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db() as conn:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending',"
            "  created_at TEXT NOT NULL,"
            "  owner_id INTEGER"
            ")"
        )
        conn.execute(
            "CREATE TABLE IF NOT EXISTS users ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  username TEXT NOT NULL UNIQUE,"
            "  password_hash TEXT NOT NULL"
            ")"
        )
    migrate()


def migrate():
    with get_db() as conn:
        columns = [row[1] for row in conn.execute("PRAGMA table_info(tasks)").fetchall()]
        if "owner_id" not in columns:
            conn.execute("ALTER TABLE tasks ADD COLUMN owner_id INTEGER")
            conn.commit()


def hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")


def check_password(password: str, password_hash: str) -> bool:
    return bcrypt.checkpw(password.encode("utf-8"), password_hash.encode("utf-8"))


class BaseRepository(ABC):
    """Abstract base class with common CRUD operations."""

    @property
    @abstractmethod
    def table_name(self) -> str:
        raise NotImplementedError

    def _get_db(self):
        return get_db()

    def _fetch_one(self, query: str, params=()):
        with self._get_db() as conn:
            row = conn.execute(query, params).fetchone()
            return dict(row) if row else None

    def _fetch_all(self, query: str, params=()):
        with self._get_db() as conn:
            rows = conn.execute(query, params).fetchall()
            return [dict(r) for r in rows]

    def _execute(self, query: str, params=()):
        with self._get_db() as conn:
            cursor = conn.execute(query, params)
            conn.commit()
            return cursor.lastrowid

    def get_by_id(self, record_id: int):
        return self._fetch_one(
            f"SELECT * FROM {self.table_name} WHERE id = ?", (record_id,)
        )

    def create(self, data: dict):
        columns = ", ".join(data.keys())
        placeholders = ", ".join("?" for _ in data)
        record_id = self._execute(
            f"INSERT INTO {self.table_name} ({columns}) VALUES ({placeholders})",
            tuple(data.values()),
        )
        return self.get_by_id(record_id)

    def update(self, record_id: int, fields: dict):
        if not fields:
            return self.get_by_id(record_id)
        assignments = ", ".join(f"{column} = ?" for column in fields)
        params = tuple(fields.values()) + (record_id,)
        self._execute(
            f"UPDATE {self.table_name} SET {assignments} WHERE id = ?", params
        )
        return self.get_by_id(record_id)

    def delete(self, record_id: int):
        self._execute(f"DELETE FROM {self.table_name} WHERE id = ?", (record_id,))

    def all(self):
        return self._fetch_all(f"SELECT * FROM {self.table_name}")


class UserRepository(BaseRepository):
    """Repository for the users table."""

    table_name = "users"

    def create_user(self, username: str, password: str) -> dict:
        password_hash = hash_password(password)
        record_id = self._execute(
            "INSERT INTO users (username, password_hash) VALUES (?, ?)",
            (username, password_hash),
        )
        return {"id": record_id, "username": username}

    def get_by_username(self, username: str) -> dict | None:
        return self._fetch_one("SELECT * FROM users WHERE username = ?", (username,))


class TaskRepository(BaseRepository):
    """Repository for the tasks table."""

    table_name = "tasks"

    def create_task(self, owner_id: int, title: str) -> dict:
        now = datetime.utcnow().isoformat()
        record_id = self._execute(
            "INSERT INTO tasks (title, status, created_at, owner_id) VALUES (?, ?, ?, ?)",
            (title, "pending", now, owner_id),
        )
        return {
            "id": record_id,
            "title": title,
            "status": "pending",
            "created_at": now,
            "owner_id": owner_id,
        }

    def get_tasks(self, owner_id: int):
        return self._fetch_all(
            "SELECT * FROM tasks WHERE owner_id = ? ORDER BY created_at DESC",
            (owner_id,),
        )

    def get_task(self, task_id: int, owner_id: int) -> dict | None:
        return self._fetch_one(
            "SELECT * FROM tasks WHERE id = ? AND owner_id = ?",
            (task_id, owner_id),
        )

    def update_task(
        self, task_id: int, owner_id: int, title: str | None = None, status: str | None = None
    ) -> dict | None:
        if self.get_task(task_id, owner_id) is None:
            return None
        fields = {}
        if title is not None:
            fields["title"] = title
        if status is not None:
            fields["status"] = status
        if fields:
            self.update(task_id, fields)
        return self.get_task(task_id, owner_id)

